"""EDA of mileage on cleaned/merged.csv. read-only."""
import pandas as pd, numpy as np
d = pd.read_csv('../cleaned/merged.csv', encoding='utf-8-sig')
m = d.mileage; age = 2026 - d.year; kmy = m / age.clip(lower=1)
print('rows', len(d), '| nulls', int(m.isna().sum()), '| dtype', m.dtype)
print('describe', m.describe().round(0).to_dict())
print('quantiles', m.quantile([.01, .05, .1, .25, .5, .75, .9, .95, .99]).round(0).to_dict())
print('\n== structure')
e500 = (m % 5000 == 2500); k1 = (m % 1000 == 0); print('midpoint-of-5000-bucket (ends 2500/7500):', int(e500.sum()), '| multiple of 1000:', int(k1.sum()), '| other (exact-looking):', int((~e500 & ~k1).sum()))
print('top values', m.value_counts().head(12).to_dict())
print('exactly 2,500:', int((m == 2500).sum()), '| 300,000:', int((m == 300000).sum()), '| 297,500-300,000:', int(m.between(297500, 300000).sum()), '| 295,000-297,499:', int(m.between(295000, 297499).sum()))
ex = m[~e500 & ~k1]; print('exact-looking values:', len(ex), 'median', int(ex.median()), 'min', int(ex.min()), 'max', int(ex.max()))
print('\n== 2,500 placeholder by age')
t = pd.DataFrame({'n': d.groupby(age).size(), 'm2500': d[m == 2500].groupby(age).size()}).fillna(0).astype(int); t['pct'] = (t.m2500 / t.n * 100).round(1)
print(t.head(22).T.to_string())
print('age>=3 & m==2500:', int(((age >= 3) & (m == 2500)).sum()), '| age>=5:', int(((age >= 5) & (m == 2500)).sum()), '| age>=10:', int(((age >= 10) & (m == 2500)).sum()))
print('\n== median mileage by year'); print(d.groupby('year').mileage.median().astype(int).to_dict())
print('\n== km/year'); print(kmy.quantile([.01, .05, .25, .5, .75, .95, .99, 1]).round(0).to_dict())
print('km/yr < 1000 & age>=3:', int(((kmy < 1000) & (age >= 3)).sum()), '(of which m==2500:', int(((kmy < 1000) & (age >= 3) & (m == 2500)).sum()), ')')
print('km/yr < 1000 & age>=3 & m!=2500:', int(((kmy < 1000) & (age >= 3) & (m != 2500)).sum()))
print('km/yr 50k-60k:', int(((kmy > 50000) & (kmy <= 60000)).sum()), '| 40k-50k:', int(((kmy > 40000) & (kmy <= 50000)).sum()))
print('year>=2025 mileage >20,000:', int(((d.year >= 2025) & (m > 20000)).sum()), '| year 2026 >10,000:', int(((d.year == 2026) & (m > 10000)).sum()))
print('\n== by group'); 
print('fuel median:', d.groupby('fuel').mileage.median().astype(int).to_dict()); print('car_type median:', d.groupby('car_type').mileage.median().astype(int).to_dict()); print('gear median:', d.groupby('gear').mileage.median().astype(int).to_dict())
print('\n== within (brand,model,year) n>=8: mileage > 3x group median and > 150,000')
g = d.groupby(['brand', 'model', 'year']).mileage.transform('median'); n = d.groupby(['brand', 'model', 'year']).mileage.transform('size')
x = d[(n >= 8) & (m > 3 * g) & (m > 150000)]; print(len(x))
print('mileage vs price (log) spearman:', round(d[['mileage', 'price']].corr(method='spearman').iloc[0, 1], 3))
w = d[(n >= 8)].copy(); w['pr'] = w.price / w.groupby(['brand', 'model', 'year']).price.transform('median'); w['mr'] = w.mileage / g[w.index]
print('price>1.8x group median while mileage>1.5x group median:', int(((w.pr > 1.8) & (w.mr > 1.5)).sum()))
